// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.OptionalLong;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.algebra.Distinct;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.Union;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.EvaluationStatistics;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.explanation.TelemetryMetricNames;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * {@link LmdbEvaluationStatistics} publishes runtime feedback into the store-wide learned state only when it has been
 * bound to a committed snapshot epoch. An unbound instance or one bound to an absent epoch (a query reading through an
 * uncommitted changeset overlay) fails closed on every publication channel (review finding 3.7.1).
 */
class LmdbFeedbackPublicationScopeTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P1 = VF.createIRI("urn:test:p1");
	private static final IRI P2 = VF.createIRI("urn:test:p2");
	private static final String NOT_EXISTS_QUERY = """
			SELECT * WHERE {
				?person <urn:test:memberOf> ?organization .
				FILTER NOT EXISTS { ?person <urn:test:blockedBy> ?blocker }
			}
			""";

	@Test
	void unboundStatisticsMustNotPublishFeedback(@TempDir Path tempDir) throws Exception {
		LmdbOperatorFeedbackStats feedback = new LmdbOperatorFeedbackStats(estimatorPath(tempDir));
		LmdbEvaluationStatistics statistics = new LmdbEvaluationStatistics(null, null, null, null, feedback, null);

		assertNoPublication(statistics, feedback, "an unbound statistics instance");
	}

	@Test
	void statisticsBoundToAnUncommittedOverlayMustNotPublishFeedback(@TempDir Path tempDir) throws Exception {
		LmdbOperatorFeedbackStats feedback = new LmdbOperatorFeedbackStats(estimatorPath(tempDir));
		LmdbEvaluationStatistics statistics = new LmdbEvaluationStatistics(null, null, null, null, feedback, null);
		statistics.bindExecutionSnapshot(OptionalLong.empty());

		assertNoPublication(statistics, feedback, "a query reading an uncommitted changeset overlay");
	}

	@Test
	void statisticsBoundToACommittedSnapshotPublishFeedback(@TempDir Path tempDir) throws Exception {
		LmdbOperatorFeedbackStats feedback = new LmdbOperatorFeedbackStats(estimatorPath(tempDir));
		LmdbEvaluationStatistics statistics = new LmdbEvaluationStatistics(null, null, null, null, feedback, null);
		statistics.bindExecutionSnapshot(OptionalLong.of(7L));

		Join join = join("s", "x", "o");
		join.setCostFeedbackTrackingEnabled(true);
		assertTrue(statistics.feedbackPublicationAllowed());
		assertTrue(statistics.shouldTrackCostFeedback(join),
				"a committed snapshot keeps runtime feedback tracking enabled");

		Union observed = observedUnion();
		statistics.recordOperatorOutcome(observed);
		assertNotNull(feedback.estimate(new Union(sp("page", P1, "review"), sp("person", P2, "award")), 600, 400, 10,
				100), "a committed snapshot publishes operator feedback");

		Filter filter = notExistsFilter();
		statistics.recordSemiAntiOutcome(filter, semiAntiObservation());
		assertNotNull(statistics.estimatorRuntime().semiAntiFeedback(filter, "NOT_EXISTS", "memoized-correlated"),
				"a committed snapshot publishes semi/anti feedback");
	}

	@Test
	void rebindingToACommittedSnapshotReopensPublication(@TempDir Path tempDir) throws Exception {
		LmdbOperatorFeedbackStats feedback = new LmdbOperatorFeedbackStats(estimatorPath(tempDir));
		LmdbEvaluationStatistics statistics = new LmdbEvaluationStatistics(null, null, null, null, feedback, null);
		statistics.bindExecutionSnapshot(OptionalLong.empty());
		assertFalse(statistics.feedbackPublicationAllowed());
		statistics.bindExecutionSnapshot(OptionalLong.of(1L));
		assertTrue(statistics.feedbackPublicationAllowed());
		statistics.bindExecutionSnapshot(OptionalLong.empty());
		assertFalse(statistics.feedbackPublicationAllowed());
	}

	private static void assertNoPublication(LmdbEvaluationStatistics statistics, LmdbOperatorFeedbackStats feedback,
			String scenario) {
		assertFalse(statistics.feedbackPublicationAllowed(), scenario + " must not be allowed to publish");

		Join join = join("s", "x", "o");
		join.setCostFeedbackTrackingEnabled(true);
		assertFalse(statistics.shouldTrackCostFeedback(join),
				scenario + " must not compile runtime feedback targets");

		Union observed = observedUnion();
		statistics.recordOperatorOutcome(observed);
		assertNull(feedback.estimate(new Union(sp("page", P1, "review"), sp("person", P2, "award")), 600, 400, 10,
				100), scenario + " must not publish operator feedback");

		Filter filter = notExistsFilter();
		statistics.recordSemiAntiOutcome(filter, semiAntiObservation());
		assertNull(statistics.estimatorRuntime().semiAntiFeedback(filter, "NOT_EXISTS", "memoized-correlated"),
				scenario + " must not publish semi/anti feedback");
	}

	private static Union observedUnion() {
		Union observed = new Union(sp("page", P1, "review"), sp("person", P2, "award"));
		// give the operator a parent so the observation goes through the per-operator (not completed-root) path
		new Distinct(observed);
		observed.setCostFeedbackTrackingEnabled(true);
		observed.setCostFeedbackExpectedRows(10.0d);
		observed.setCostFeedbackExpectedWorkRows(100.0d);
		observed.setCostFeedbackReportQErrorThreshold(LmdbOperatorFeedbackStats.DEFAULT_REPORT_Q_ERROR_THRESHOLD);
		observed.setResultSizeEstimate(10.0d);
		observed.setCostEstimate(100.0d);
		observed.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_WORK_ROWS, 100.0d);
		observed.setCostFeedbackActualRows(1_000L);
		observed.setCostFeedbackActualWorkRows(1_000.0d);
		observed.setCostFeedbackCloseCountActual(1L);
		observed.setCostFeedbackCompletedActual(true);
		observed.setLongMetricActual(TelemetryMetricNames.EXHAUSTED_CLOSE_COUNT_ACTUAL, 1);
		return observed;
	}

	private static EvaluationStatistics.SemiAntiOutcomeObservation semiAntiObservation() {
		return new EvaluationStatistics.SemiAntiOutcomeObservation("NOT_EXISTS", "memoized-correlated",
				"memoized-correlated", 10L, 6L, 4L, 4L, 2L, 2L, 6L, 18L, 4L, 4L, 0L, 0L, 10L, true, "", "");
	}

	private static Filter notExistsFilter() {
		Filter[] found = new Filter[1];
		TupleExpr parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, NOT_EXISTS_QUERY, null)
				.getTupleExpr();
		parsed.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter node) {
				if (found[0] == null) {
					found[0] = node;
				}
				super.meet(node);
			}
		});
		return found[0];
	}

	private static Join join(String leftSubject, String sharedName, String rightObject) {
		return new Join(sp(leftSubject, P1, sharedName), sp(sharedName, P2, rightObject));
	}

	private static StatementPattern sp(String subjectName, IRI predicate, String objectName) {
		return new StatementPattern(Var.of(subjectName), Var.of("_p", predicate, true, true), Var.of(objectName));
	}

	private static Path estimatorPath(Path tempDir) throws Exception {
		Path estimatorPath = tempDir.resolve("join-estimator.rjes");
		Files.createDirectories(estimatorPath);
		Files.writeString(estimatorPath.resolve("metadata.bin"), "metadata");
		return estimatorPath;
	}
}
